export const BODY: string = "\n<p>کور ویب وائٹلز گوگل کے وہ پیمانے ہیں جو بتاتے ہیں کہ ویب سائٹ صارف کو کیسی محسوس ہوتی ہے۔ ان میں لوڈنگ کی رفتار، صفحے کا استحکام اور ردعمل کی تیزی شامل ہیں۔</p>\n<p>تصویریں ان تینوں پیمانوں پر سب سے زیادہ اثر ڈالتی ہیں۔ بھاری ہیرو تصویر صفحہ سست کرتی ہے، بغیر سائز والی تصویر مواد کو ہلا دیتی ہے، اور بھاری صفحہ بٹنوں کا جواب دیر سے دیتا ہے۔</p>\n<p>یہ مضمون ہر پیمانے کی وضاحت، تصویروں سے اس کا تعلق، درست کرنے کے مراحل اور ترجیح کا حکم بتاتا ہے۔ تصویریں بہتر بنانے کے لیے <a href=\"/ur/website-ke-liye-tasveer-optimize-karein/\">ویب امیج آپٹیمائزر</a> استعمال کریں۔</p>\n<h2 id=\"what-are-cwv\">کور ویب وائٹلز کیا ہیں؟</h2>\n<p>کور ویب وائٹلز تین پیمانے ہیں: LCP جو سب سے بڑا مواد کب نظر آتا ہے، CLS جو صفحہ کتنا ہلتا ہے، اور INP جو کلک کا جواب کتنی جلدی ملتا ہے۔ گوگل ان تینوں کو درجہ بندی میں استعمال کرتا ہے۔</p>\n<p>یہ پیمانے لیب میں نہیں، اصل صارفین کے فون اور کمپیوٹر پر ناپے جاتے ہیں۔ اس لیے تیز انٹرنیٹ پر اچھا اسکور موبائل ڈیٹا پر خراب بھی ہو سکتا ہے۔</p>\n<h2 id=\"lcp-explained\">LCP: ہیرو تصویر فیصلہ کیوں کرتی ہے</h2>\n<p>LCP وہ وقت ہے جب صفحے کا سب سے بڑا مواد نظر آتا ہے، اور اکثر وہ ہیرو تصویر ہوتی ہے۔ اگر ہیرو تصویر بھاری ہو تو LCP دیر سے ہوتا ہے اور صارف کو صفحہ خالی لگتا ہے۔</p>\n<p>اچھا LCP ڈھائی سیکنڈ سے کم ہوتا ہے۔ ہیرو تصویر کو چھوٹا، WebP میں اور جلد لوڈ ہونے والا بنانا LCP بہتر کرنے کا سب سے تیز طریقہ ہے۔</p>\n<h2 id=\"fixing-lcp\">سست LCP قدم بہ قدم ٹھیک کرنا</h2>\n<p>پہلے ہیرو تصویر کو کمپریس کریں اور اس کے ابعاد دکھائی دینے والے سائز تک کم کریں۔ پھر اسے لیزی لوڈنگ سے ہٹائیں، کیونکہ ہیرو تصویر کو فوراً لوڈ ہونا چاہیے۔</p>\n<p>آخر میں تصویر کو پہلے سے لوڈ کرنے کا اشارہ دیں، تاکہ براؤزر اسے ترجیح دے۔ یہ تین قدم اکثر LCP کو سیکنڈوں سے کم کر کے اچھے حد میں لے آتے ہیں۔</p>\n<h2 id=\"cls-explained\">CLS: تصویریں ترتیب کیسے ہلاتی ہیں</h2>\n<p>CLS وہ پیمانہ ہے جو بتاتا ہے کہ لوڈ ہوتے وقت مواد کتنا اپنی جگہ بدلتا ہے۔ بغیر چوڑائی اور اونچائی والی تصویر لوڈ ہونے پر اچانک جگہ لیتی ہے اور نیچے کا مواد دھکیل دیتی ہے۔</p>\n<p>صارف اسی وقت بٹن دبانے والا ہوتا ہے جب مواد ہل جاتا ہے، اور وہ غلط چیز دبا بیٹھتا ہے۔ یہی تجربہ CLS ناپتا ہے، اور اس کا اچھا اسکور 0.1 سے کم ہوتا ہے۔</p>\n<h2 id=\"inp-explained\">INP: تصویر کا وزن ردعمل کیسے سست کرتا ہے</h2>\n<p>INP کلک سے لے کر جواب تک کا وقت ہے۔ بھاری تصویریں براؤزر کو مصروف رکھتی ہیں، اس لیے کلک کا جواب دیر سے ملتا ہے، خاص طور پر کمزور فون پر۔</p>\n<p>تصویروں کا وزن کم کرنے سے براؤزر آزاد ہوتا ہے اور بٹن تیزی سے جواب دیتے ہیں۔ اچھا INP دو سو ملی سیکنڈ سے کم ہوتا ہے۔</p>\n<h2 id=\"measuring-cwv\">کور ویب وائٹلز کو درست طریقے سے ناپنا</h2>\n<p>ناپنے کے لیے PageSpeed Insights استعمال کریں، جو لیب اور اصل صارفین دونوں کا ڈیٹا دکھاتا ہے۔ لیب ڈیٹا تیز کمپیوٹر پر بنتا ہے، جبکہ فیلڈ ڈیٹا اصل صارفین کی حقیقت بتاتا ہے۔</p>\n<p>ایک بار ناپنا کافی نہیں: مختلف وقت اور مختلف صفحات پر ناپیں۔ ہیرو تصویر بدلنے کے بعد دوبارہ ناپیں، تاکہ بہتری کی تصدیق ہو سکے۔</p>\n<h2 id=\"image-budgets\">صفحے کے لیے تصویر کا بجٹ طے کرنا</h2>\n<p>تصویر کا بجٹ وہ حد ہے جو آپ ہر صفحے کی تصویروں کے کل وزن کے لیے طے کرتے ہیں، جیسے ایک میگا بائٹ سے کم۔ بجٹ طے کرنے سے ٹیم ہر تصویر کو سوچ سمجھ کر شامل کرتی ہے۔</p>\n<p>بجٹ کو ہیرو، مصنوعات اور تھمب نیل میں تقسیم کریں۔ ہیرو کو سب سے زیادہ حصہ دیں، کیونکہ وہ سب سے اہم ہے، اور تھمب نیل کو سب سے کم۔</p>\n<h2 id=\"formats-cwv\">فارمیٹ اور کور ویب وائٹلز</h2>\n<p>WebP JPG سے چھوٹا ہوتا ہے، اس لیے وہ LCP بہتر کرتا ہے۔ AVIF اس سے بھی چھوٹا ہے، مگر ہر براؤزر میں نہیں چلتا۔</p>\n<p>فارمیٹ بدلنا سب سے آسان جیت ہے: تصویریں بدلے بغیر صرف فارمیٹ بدلنے سے صفحہ ہلکا ہو جاتا ہے اور تینوں پیمانے بہتر ہوتے ہیں۔</p>\n<h2 id=\"responsive-images\">ریسپانسیو تصویریں اور ریزولوشن بدلنا</h2>\n<p>ریسپانسیو تصویریں ہر آلے کو اس کے سائز کی تصویر دیتی ہیں: فون کو چھوٹی، ڈیسک ٹاپ کو بڑی۔ اس سے فون پر میگا بائٹس بچتے ہیں اور LCP تیزی سے بہتر ہوتا ہے۔</p>\n<p>اس کے لیے تصویر کے کئی سائز بنائیں اور براؤزر کو چننے دیں۔ ایک ہی بڑی تصویر سب کو دینا موبائل صارفین پر ظلم ہے۔</p>\n<h2 id=\"common-cwv-mistakes\">کور ویب وائٹلز کی عام غلطیاں</h2>\n<p>سب سے عام غلطی ہیرو تصویر پر لیزی لوڈنگ لگانا ہے، جس سے LCP خراب ہو جاتا ہے۔ دوسری غلطی تصویروں کو بغیر ابعاد کے چھوڑنا ہے، جس سے CLS بڑھ جاتا ہے۔</p>\n<p>تیسری غلطی صرف لیب اسکور دیکھنا ہے۔ لیب میں اچھا اسکور اصل صارفین کے خراب تجربے کو چھپا سکتا ہے، اس لیے فیلڈ ڈیٹا ہمیشہ دیکھیں۔</p>\n<h2 id=\"priority-order\">پہلے کیا ٹھیک کریں: ترجیح کا حکم</h2>\n<p>پہلے LCP ٹھیک کریں، کیونکہ وہ صارف کو سب سے پہلے محسوس ہوتا ہے۔ ہیرو تصویر کمپریس کریں اور اسے ترجیح سے لوڈ کریں۔</p>\n<p>پھر CLS ٹھیک کریں: سب تصویروں کو ابعاد دیں۔ آخر میں INP دیکھیں، کیونکہ وہ اکثر پہلے دو ٹھیک کرنے سے خود بہتر ہو جاتا ہے۔</p>\n<h2 id=\"field-vs-lab\">فیلڈ ڈیٹا بمقابلہ لیب ڈیٹا</h2>\n<p>فیلڈ ڈیٹا اصل صارفین سے آتا ہے اور گوگل کی درجہ بندی میں یہی استعمال ہوتا ہے۔ لیب ڈیٹا کنٹرول شدہ ماحول میں بنتا ہے اور جانچ کے لیے اچھا ہے، مگر حقیقت نہیں۔</p>\n<p>دونوں کو ساتھ دیکھیں: لیب سے مسئلہ تلاش کریں اور فیلڈ سے تصدیق کریں کہ اصل صارفین کو فائدہ ہوا یا نہیں۔</p>\n<h2 id=\"lcp-images-vs-text\">جب LCP عنصر تصویر نہ ہو</h2>\n<p>کبھی کبھی سب سے بڑا مواد سرخی یا متن ہوتا ہے، تصویر نہیں۔ اس صورت میں فونٹ اور سرور کا وقت اہم ہو جاتا ہے، تصویریں نہیں۔</p>\n<p>پھر بھی تصویریں پس منظر میں بینڈ وڈتھ کھا سکتی ہیں۔ ہیرو متن والے صفحے پر بھی باقی تصویریں ہلکی رکھیں، تاکہ متن جلدی نظر آئے۔</p>\n<h2 id=\"cls-fonts\">تصویروں سے آگے CLS: فونٹ اور اشتہار</h2>\n<p>CLS صرف تصویروں سے نہیں بنتا: دیر سے لوڈ ہونے والے فونٹ متن کو ہلاتے ہیں، اور اچانک ظاہر ہونے والے اشتہار مواد کو دھکیلتے ہیں۔</p>\n<p>فونٹ کے لیے جگہ پہلے سے مختص کریں اور اشتہار کے لیے طے شدہ جگہ رکھیں۔ تصویر، فونٹ اور اشتہار، تینوں کو جگہ دینا ہی CLS کو قابو کرتا ہے۔</p>\n<h2 id=\"inp-scripts\">INP اور بھاری اسکرپٹس</h2>\n<p>INP اکثر بھاری جاوا اسکرپٹ سے خراب ہوتا ہے، جو کلک کے جواب میں رکاوٹ بنتی ہے۔ تصویریں ہلکی کرنے کے ساتھ غیر ضروری اسکرپٹ بھی ہٹائیں۔</p>\n<p>تیسری پارٹی کے ویجٹ، جیسے چیٹ اور تجزیہ، INP کو سب سے زیادہ نقصان پہنچاتے ہیں۔ انہیں دیر سے لوڈ کریں یا صرف ضرورت پر چلائیں۔</p>\n<h2 id=\"mobile-first\">موبائل پہلے: فون اسکور سب سے اہم کیوں ہیں</h2>\n<p>زیادہ تر وزیٹر فون سے آتے ہیں، اور فون کا پروسیسر اور انٹرنیٹ دونوں کمزور ہوتے ہیں۔ اسی لیے موبائل اسکور ڈیسک ٹاپ سے ہمیشہ خراب ہوتا ہے۔</p>\n<p>گوگل موبائل تجربے کو درجہ بندی میں ترجیح دیتا ہے۔ ڈیسک ٹاپ پر اچھا اسکور کافی نہیں، موبائل پر اچھا اسکور ہی اصل کامیابی ہے۔</p>\n<h2 id=\"ongoing-monitoring\">کور ویب وائٹلز کی مسلسل نگرانی</h2>\n<p>ایک بار ٹھیک کرنا کافی نہیں: نئی تصویریں اور نئے اشتہار اسکور دوبارہ خراب کر سکتے ہیں۔ ہر مہینے PageSpeed Insights سے دوبارہ جانچیں۔</p>\n<p>نگرانی کو ٹیم کی عادت بنائیں: نئی تصویر شامل کرنے سے پہلے اس کا وزن جانچیں، اور بڑی تبدیلی کے بعد اسکور دوبارہ ناپیں۔</p>\n<h2 id=\"final-check-cwv\">شائع کرنے سے پہلے آخری جانچ</h2>\n<p>شائع کرنے سے پہلے تین چیزیں جانچیں: ہیرو تصویر کمپریس اور ترجیح سے لوڈ ہو، سب تصویروں کے ابعاد لکھے ہوں، اور صفحے کا کل وزن بجٹ کے اندر ہو۔</p>\n<p>یہ آخری جانچ چند منٹ لیتی ہے اور خراب تجربے سے بچاتی ہے۔ رفتار کی مکمل رہنمائی <a href=\"/ur/blog/website-speed-ke-liye-tasveer-kaise-optimize-karein/\">ویب سائٹ کی رفتار کے لیے تصویریں بہتر بنائیں</a> اور <a href=\"/ur/blog/web-tasveer-optimizer-rehnumai/\">ویب امیج آپٹیمائزر رہنما</a> میں پڑھیں۔ بلک کمپریشن کے لیے <a href=\"/ur/bulk-tasveer-compress-karein/\">بلک امیج کمپریسر</a> استعمال کریں۔</p>\n";

